# Chip Chip ## Быстрый старт Быстрый старт ```tsx
import React from 'react';
import { Chip } from '@salutejs/sdds-finai';
import { IconDownload } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
            <Chip text="Текст" />
            <Chip text="Текст" contentLeft={<IconDownload color="inherit" />} />
            <Chip text="Текст" hasClear={false} />
        </div>
    );
}
```

## Управление внешним видом Управление внешним видом Внешний вид компонента определяется свойствами  `view`  и  `size` : ```tsx
import React from 'react';
import { Chip } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
            <Chip text="Default" view="default" />
            <Chip text="Secondary" view="secondary" />
            <Chip text="Accent" view="accent" />
            <Chip text="Positive" view="positive" />
            <Chip text="Warning" view="warning" />
            <Chip text="Negative" view="negative" />
        </div>
    );
}
```

